from sendgrid import SendGridAPIClient
from sendgrid.helpers.mail import Mail

_sg = SendGridAPIClient(os.getenv('SENDGRID_API_KEY'))
FROM_EMAIL = os.getenv('SENDGRID_FROM_EMAIL')
FROM_NAME = os.getenv('SENDGRID_FROM_NAME', 'App')

def send_email(to_email: str, subject: str, html_content: str, plain_content: str = '') -> bool:
    message = Mail(
        from_email=(FROM_EMAIL, FROM_NAME),
        to_emails=to_email,
        subject=subject,
        html_content=html_content,
        plain_text_content=plain_content or html_content,
    )
    try:
        response = _sg.send(message)
        return response.status_code in (200, 202)
    except Exception as e:
        return False

def send_template_email(to_email: str, template_id: str, dynamic_data: dict) -> bool:
    message = Mail(from_email=(FROM_EMAIL, FROM_NAME), to_emails=to_email)
    message.template_id = template_id
    message.dynamic_template_data = dynamic_data
    try:
        response = _sg.send(message)
        return response.status_code in (200, 202)
    except Exception:
        return False

