const sgMail = require('@sendgrid/mail');
sgMail.setApiKey(process.env.SENDGRID_API_KEY);

const FROM = { email: process.env.SENDGRID_FROM_EMAIL, name: process.env.SENDGRID_FROM_NAME || 'App' };

const sendEmail = async (to, subject, htmlContent, textContent) => {
  try {
    await sgMail.send({ to, from: FROM, subject, html: htmlContent, text: textContent || htmlContent });
    return true;
  } catch (e) { return false; }
};

const sendTemplateEmail = async (to, templateId, dynamicData) => {
  try {
    await sgMail.send({ to, from: FROM, templateId, dynamicTemplateData: dynamicData });
    return true;
  } catch (e) { return false; }
};
